tests.code:
for bad in ("12:00:00", "0.12:00", "a.00:00:00", "0.24:00:00", "0.00:60:00", ""):
    try:
        parse_timeout(bad)
    except ValueError:
        continue
    raise AssertionError(bad)

try:
    parse_timeout("7.00:00:01")
except ValueError:
    pass
else:
    raise AssertionError("over seven days accepted")

exercises.starter:
def parse_timeout(value):
    days, rest = value.split(".")
    h, m, s = rest.split(":")
    return int(days) * 86400 + int(h) * 3600 + int(m) * 60 + int(s)
